#!/usr/bin/env python3
"""Generate the pokeemerald overworld sprites of RFVF+ (the OBJ_EVENT_GFX_HOENN_* graphics ids) from pret/pokeemerald.

Usage (Git Bash, from the repo root), then build as usual:
    uv run --no-project --with pillow python tools/hoenn_import/hoenn_sprites.py [--emerald ../pokeemerald] [--check]
    --check: write nothing, exit 1 if a generated file would change (re-running with the same pokeemerald changes
    nothing).

Every Emerald object graphic is imported but those skipped() leaves out (player avatar states, link avatars, berry
trees, secret base decorations): OBJ_EVENT_GFX_HOENN_X shows Emerald's OBJ_EVENT_GFX_X with Emerald's pixels, palettes,
frames and animations. Hoenn layouts load Emerald's NPC palettes (InitObjectEventPalettes(OBJ_PAL_MODE_HOENN)), so a Hoenn
map uses these ids (hoenn_import.py maps Emerald objects to them) and a Kanto map never does (--check-gfx).

GRAPHICS IDS ARE STORED IN SAVES: the OBJ_EVENT_GFX_HOENN_ ids already defined keep their numbers; the missing ones are
appended after the highest one, in Emerald id order, inside the Hoenn block (256-511). Never renumber or remove one.

Written between "BEGIN/END generated by tools/hoenn_import/hoenn_sprites.py: <block>" comment lines (the rest of
each file is left alone; Porymap reads these files, so the blocks follow the surrounding patterns):
  include/constants/event_objects.h             ids, NUM_OBJ_EVENT_GFX
  src/data/object_events/object_event_graphics.h  INCBINs: graphics/object_events/pics/hoenn/**, palettes/hoenn_*
  src/data/object_events/object_event_pic_tables.h, object_event_anims.h (+ sStepAnimTables),
      object_event_graphics_info.h, object_event_graphics_info_pointers.h (declarations, pointers, variants)
  src/event_object_movement.c                   palette tags, sObjectEventSpritePalettes, reflection palette sets
  src/dynamic_placeholder_text_util.c           text colors of the Hoenn ids
  spritesheet_rules.mk                          4bpp rules (Emerald's own rule of each sheet, if it has one)
  graphics/object_events/pics/hoenn/**.png, graphics/object_events/palettes/hoenn_*.pal: copies of Emerald's files
    (pics/<category>/<path> -> pics/hoenn/<path>, palettes/<name>.pal -> palettes/hoenn_<name>.pal)

How each part is ported:
  - graphics info: field by field; paletteSlot is the same slot (same enum, Hoenn maps load Emerald's palettes there);
    paletteTag NPC_N -> HOENN_NPC_N, a special palette X -> HOENN_X (+ its reflections, gSpecialObjectReflection-
    PaletteSets); reflectionPaletteTag -> this repo's tag of the same name (checked: same palette).
  - pic tables: Emerald's frames in Emerald's order. When the anim table used here shows a later frame, copies of
    frame 0 follow, so no frame past the table is ever read (this repo's sAnimTable_Standard has ANIM_RAISE_HAND,
    FRLG's VS Seeker, on frame 9; Emerald walkers have frames 0-8).
  - anim tables: this repo's table when it plays the same anims at every Emerald index and has the same
    sStepAnimTables entry (it may have more anims), else Emerald's, as sAnimTable_HoennX with its sAnim_HoennY (an
    anim this repo has with the same name and commands is shared). Subsprite tables and base OAMs: this repo's
    (checked equal to Emerald's).
  - text colors: pokeemerald has no NPC text color table (it prints every NPC in the same colors). FRLG's rule by
    Emerald's own graphics folder: pokemon/ -> MON, misc/ -> NEUTRAL, people/ -> FEMALE (FEMALE below) or MALE.
  - VARIANTS: sHoennVariantGraphicsInfoPointers, the sprite a Hoenn map shows for a Kanto id (safety net only).
"""
import argparse
import re
import shutil
import sys
from pathlib import Path

from PIL import Image

REPO = Path(__file__).resolve().parents[2]
TOOL = "generated by tools/hoenn_import/hoenn_sprites.py"
OBJ = "src/data/object_events/"
PICS = "graphics/object_events/pics/"
PALS = "graphics/object_events/palettes/"
HOENN_IDS = range(256, 512)  # event_objects.h: HOENN_OBJ_EVENT_GFX_BASE; the next region starts at 512
FIRST_PAL_TAG = 0x1125  # first free tag after this repo's OBJ_EVENT_PAL_TAG_LADY (src/event_object_movement.c)
INFO_FIELDS = ["tileTag", "paletteTag", "reflectionPaletteTag", "size", "width", "height", "paletteSlot",
               "shadowSize", "inanimate", "disableReflectionPaletteLoad", "tracks", "oam", "subspriteTables",
               "anims", "images", "affineAnims"]


def skipped(name):
    """Emerald gfx not imported: the player is Red/Leaf, link partners are drawn by FRLG's own code, FRLG has no
    berry trees nor secret bases."""
    return bool(re.fullmatch(r"(BRENDAN|MAY)_(NORMAL|MACH_BIKE|ACRO_BIKE|SURFING|FIELD_MOVE|UNDERWATER|FISHING|"
                             r"WATERING|DECORATING)|LINK_(RS_)?(BRENDAN|MAY)|RED|LEAF|BERRY_TREE\w*|\w+_(DOLL|CUSHION)",
                             name))


